(function(root,factory){const common=typeof module==='object'&&module.exports;const api=factory(common?require('./engine.js'):root.TravellerEngine,common?require('./english.js'):root.TravellerEnglish);if(common)module.exports=api;else root.TravellerFinishingUI=api})(globalThis,function(E,L){
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const en=x=>esc(L.english(x)),money=n=>'Cr'+Number(n||0).toLocaleString('en-GB');
const opts=(list,value)=>list.map(([id,label])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
function view(g,ui={}){const f=g.finishing||{connections:[],allocations:[]},r=ui.rules||g.rules||{method:'random'};let title,content,kicker='Finishing Touches';
 if(g.phase==='creationmode'){kicker='Before the homeworld';title='Choose the creation rules.';content=`<p>Use the standard career life path or one of the Core Rulebook variants. These settings are fixed once you begin.</p><label class="form-field">Creation method<select data-rule="method">${opts([['random','Standard · roll Skills and Training'],['choose','Choose Skills · select table results'],['pointbuy','Point Allocation · buy characteristics, skills and rank']],r.method)}</select></label><label class="confirmation"><input type="checkbox" data-rule="solo" ${r.solo?'checked':''}>Solo Creation — campaign connections and one skill at level 1 instead of a group pack</label><label class="confirmation"><input type="checkbox" data-rule="ironMan" ${r.ironMan?'checked':''}>Iron Man — a failed Survival check kills the character</label><p class="note">Iron Man uses Survival rolls and cannot be combined with Point Allocation. Psion remains available only through a Life Event encounter.</p>`}
 else if(g.phase==='connections'){title='Complete your Connections.';content=`<p>Record up to two ${g.rules?.solo?'connections with a campaign person, organisation or place':'agreed connections with different player characters'}. Each gives one skill increase, up to level 3. Jack-of-all-Trades is excluded.</p>${f.connections.length?`<ul class="text-list">${f.connections.map(c=>`<li><strong>${esc(c.partner)}</strong> · ${en(c.skill)} ${c.level}<br>${esc(c.description)}</li>`).join('')}</ul>`:'<p class="note">No Connections recorded. You can continue without claiming a bonus.</p>'}${f.connections.length<2?`<div class="connection-form"><label class="form-field">${g.rules?.solo?'Campaign person, organisation or place':'Other player character'}<input data-connection="partner" maxlength="80" value="${esc(ui.connection?.partner||'')}"></label><label class="form-field">Shared event<textarea data-connection="description" maxlength="500" rows="2">${esc(ui.connection?.description||'')}</textarea></label><label class="form-field">Skill<select data-connection="skill">${opts(E.leafSkills(g).filter(n=>n!=='Мастер на все руки'&&(g.skills[n]||0)<3).map(n=>[n,L.english(n)+' · '+(g.skills[n]||0)+' → '+((g.skills[n]||0)+1)]),ui.connection?.skill||'Админ')}</select></label><button class="primary" data-command="connection-submit" data-revision="${g.revision}">Record Connection &amp; gain skill</button><p class="note">${g.rules?.solo?'Use a connection established for your campaign.':'Record a connection only after both players have agreed to it.'}</p></div>`:''}`}
 else if(g.phase==='campaignpack'){title=g.rules?.solo?'Choose your Solo skill.':'Choose a Campaign Skill Pack.';content=g.rules?.solo?'<p>Solo Creation grants one skill at level 1 instead of distributing a group pack. A higher existing level is preserved.</p>':'<p>Choose the pack agreed by your group. Next, assign each listed skill once to this Traveller or another group member.</p>'}
 else if(g.phase==='packallocation'){title=E.FINISHING.packs[f.pack].name+' Skill Pack.';content=`<p>Take the skills allocated to this character and record the remaining recipients. Duplicate entries in a pack are separate awards.</p><label class="form-field">Recipient for “another Traveller”<input data-pack-recipient maxlength="80" value="${esc(ui.packRecipient||'')}" placeholder="Another character’s name"></label>${f.allocations.length?`<ul class="text-list">${f.allocations.map(a=>`<li>${en(a.name)} 1 → ${esc(a.recipient)}</li>`).join('')}</ul>`:''}`}
 else if(g.phase==='picktraining'){title='Choose your training result.';kicker='Choose Skills variant';content='<p>Select one result from your chosen career table. This replaces the training die roll; Survival, Events and other checks still use dice.</p>'}
 else if(g.phase==='pointaging'){title='Resolve aging and Benefits.';kicker='Point Allocation';content='<p>Your allocation is fixed. Resolve ordinary Aging checks for terms four and later, then your purchased Benefit rolls and normal Rank benefits.</p>'}
 else if(g.phase==='pointbuy'){const q=g.pointbuy,F=E.FINISHING,cost=F.pointCost(q),budget=F.budget(q.terms),c=E.career({activeCareer:{careerId:q.career}});title='Allocate your points.';kicker='Point Allocation';content=`<p>Buy characteristics, skills, Rank and Benefit rolls. Background Skills, career training and Events are omitted. Normal Rank awards and Aging still apply.</p><p class="point-budget"><strong>${cost.total} / ${budget} points</strong> · ${budget-cost.total} remaining<br>Characteristics: ${cost.characteristics} / minimum ${F.minimum(q.terms)} · Skills: ${cost.skills}</p><div class="point-controls"><label>Terms<select data-point="terms">${opts(Array.from({length:12},(_,i)=>[i+1,String(i+1)]),q.terms)}</select></label><label>Career<select data-point="career">${opts(E.choices({...g,phase:'careerchoice',careerHistory:[],activeCareer:null}).filter(o=>o.id!=='psion').map(o=>[o.id,o.label]),q.career)}</select></label><label>Assignment<select data-point="assignment">${opts(Object.entries(c.assignments).map(([id,a])=>[id,a.name]),q.assignment)}</select></label><label>Rank · 2 points each<select data-point="rank">${opts(Array.from({length:7},(_,i)=>[i,String(i)]),q.rank)}</select></label><label>Purchased Benefit rolls · 2 points each<select data-point="benefits">${opts(Array.from({length:q.terms*2+1},(_,i)=>[i,String(i)]),q.benefits)}</select></label>${c.military?`<label class="confirmation"><input type="checkbox" data-point="officer" ${q.officer?'checked':''}>Commission as an officer</label>`:''}</div><div class="point-stats">${L.short.map((label,i)=>`<label>${label}<select data-point="stat" data-index="${i}">${opts(Object.entries(F.statCosts).map(([v,p])=>[v,v+' · '+p+' points']),q.stats[i])}</select></label>`).join('')}</div><details open><summary>Skills · purchased ${Object.keys(q.skills).length}</summary><label class="form-field">Find a skill<input data-point-search placeholder="Pilot, Medic, Engineer…" value="${esc(ui.pointSearch||'')}"></label><div class="point-skill-list">${E.leafSkills(g).filter(n=>!E.PSIONICS.isTalent(n)).map(name=>`<label class="point-skill-row" data-skill-label="${esc(L.english(name).toLowerCase())}" ${ui.pointSearch&&!L.english(name).toLowerCase().includes(ui.pointSearch.toLowerCase())?'hidden':''}><span>${en(name)}</span><select data-point="skill" data-skill="${esc(name)}">${opts([[-1,'Not purchased'],...[0,1,2,3,4].map(n=>[n,'Level '+n+' · '+F.skillCosts[n]*(name==='Мастер на все руки'?5:1)+' points'])],q.skills[name]??-1)}</select></label>`).join('')}</div></details><p class="note">At most two purchased Benefit rolls per term. Jack-of-all-Trades costs five times the normal skill price. Military Commission is automatic; no additional points are charged for it.</p>`}
 else return null;
 return {title,kicker,content,asset:g.phase==='creationmode'?'aurora':'none'};
}
function history(g){const f=g.finishing;if(!f)return '';return `${f.connections.length?'<h3>Connections</h3><ul class="dossier-list">'+f.connections.map(c=>'<li><span>'+esc(c.partner)+' · '+en(c.skill)+' '+c.level+'</span></li>').join('')+'</ul>':''}${f.pack?'<h3>Campaign Skill Pack</h3><p>'+E.FINISHING.packs[f.pack].name+'</p>':''}${f.soloSkill?'<h3>Solo Creation</h3><p>'+en(f.soloSkill)+' 1</p>':''}`}
return {view,history};
});
